B.An=new A.d4("joint_pain","Joint / muscle pain","\u0622\u0644\u0627\u0645 \u0627\u0644\u0645\u0641\u0627\u0635\u0644","\ud83e\uddb4",!1,4,null,"Peaks 2\u20134 days after Taxol. Gentle warm compresses and light movement can help.",!1,"Does joint pain stop you moving normally?")
B.Ao=new A.d4("constipation","Constipation","\u0625\u0645\u0633\u0627\u0643","\ud83c\udf3f",!1,4,null,"Stay hydrated. Gentle movement helps. Tell your team if no bowel movement for 3+ days.",!1,"Has this lasted more than 2 days?")
B.cK=new A.d4("neuropathy","Tingling / numbness","\u062a\u0646\u0645\u064a\u0644","\ud83e\udd32",!0,7,"Severe tingling or numbness \u2014 report to your care team at next visit or call if it affects walking.","Hands and feet tingling is common with Taxol. Tell your team \u2014 dose adjustment may help.",!1,"Does tingling affect your hands or feet daily tasks?")
B.bl=new A.d4("sleep","Sleep quality","\u062c\u0648\u062f\u0629 \u0627\u0644\u0646\u0648\u0645","\ud83d\ude34",!1,4,null,"A consistent bedtime routine helps. Avoid screens 30 minutes before sleep.",!1,"Is poor sleep affecting your energy during the day?")
B.bv=new A.d4("appetite","Poor appetite","\u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0634\u0647\u064a\u0629","\ud83c\udf7d\ufe0f",!1,4,null,"Eat whatever you can tolerate. Calories matter more than nutrition right now.",!1,"Is poor appetite affecting your nutrition?")
B.bb=new A.d4("mood","Mood / anxiety","\u0627\u0644\u0645\u0632\u0627\u062c / \u0627\u0644\u0642\u0644\u0642","\ud83d\udc9c",!1,4,null,"What you're feeling is a normal response to treatment. Talking about it helps.",!0,"Is your mood affecting daily life or sleep?")
B.cn=new A.d4("nausea","Nausea","\u063a\u062b\u064a\u0627\u0646","\ud83c\udf0a",!1,4,null,"Small frequent meals every 2\u20133 hours. Cold or room-temperature foods are easier to tolerate.",!1,"Does nausea affect eating or drinking?")
B.bc=new A.d4("fatigue","Fatigue","\u0625\u0631\u0647\u0627\u0642","\ud83c\udf19",!1,4,null,"Rest when your body asks. Short 20-minute rests are better than long naps.",!1,"Does fatigue stop normal activities?")
B.co=new A.d4("mouth_sores","Mouth sores","\u062a\u0642\u0631\u062d\u0627\u062a \u0627\u0644\u0641\u0645","\ud83d\udc44",!0,6,"Severe mouth sores can make it hard to eat or drink. Contact your team if you cannot swallow.","Rinse with salt water 4\u20136 times daily. Avoid spicy, acidic, or rough-textured foods.",!1,"Do mouth sores affect eating or speaking?")
B.j9=new A.d4("fluid_retention","Fluid retention","\u0627\u062d\u062a\u0628\u0627\u0633 \u0627\u0644\u0633\u0648\u0627\u0626\u0644","\u2696\ufe0f",!1,4,null,"Weigh yourself daily at the same time. Report a gain of 2kg+ in 48 hours.",!1,"Have you gained more than 1kg since yesterday?")
B.cL=new A.d4("breathlessness","Breathlessness","\u0636\u064a\u0642 \u0627\u0644\u062a\u0646\u0641\u0633","\ud83e\udec1",!0,4,"Breathlessness at rest or with light activity \u2014 contact your care team today.",null,!1,null)
B.hc=new A.d4("hair_loss","Hair loss","\u062a\u0633\u0627\u0642\u0637 \u0627\u0644\u0634\u0639\u0631","\ud83d\udc87",!1,4,null,"This is temporary. Gentle shampoo and a soft pillow cover can reduce scalp discomfort.",!1,"Is hair loss affecting your confidence or comfort?")
B.dd=new A.d4("infection","Signs of infection","\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0639\u062f\u0648\u0649","\ud83d\udd34",!0,2,"Redness, swelling, warmth around any wound or IV site \u2014 contact your team today.",null,!1,null)
B.Rs=new A.d4("swelling","Swelling / fluid","\u062a\u0648\u0631\u0645","\ud83d\udca7",!1,4,null,"Elevate legs when resting. Avoid tight shoes. Report significant swelling.",!1,"Does swelling affect walking or wearing shoes?")
B.aQ=new A.d4("fever","Fever / Temperature","\u062d\u0645\u0649 / \u062d\u0631\u0627\u0631\u0629","\ud83c\udf21\ufe0f",!0,3,"Fever above 38\xb0C (100.4\xb0F) during chemotherapy \u2014 call your care team immediately, day or night. Do not wait.",null,!1,null)
B.Ap=new A.d4("diarrhea","Diarrhoea","\u0625\u0633\u0647\u0627\u0644","\ud83d\udca7",!0,6,"More than 4\u20136 loose stools per day \u2014 contact your team. Risk of dehydration.",null,!1,"How many episodes today?")
B.Aq=new A.d4("vomiting","Vomiting","\u0642\u064a\u0621","\ud83e\udd22",!0,5,"More than 2\u20133 episodes \u2014 contact your care team. You may need anti-nausea medication adjustment.",null,!1,"How many episodes today?")
B.Rt=new A.d4("palpitations","Heart palpitations","\u062e\u0641\u0642\u0627\u0646 \u0627\u0644\u0642\u0644\u0628","\u2764\ufe0f",!0,3,"Irregular heartbeat or chest discomfort \u2014 contact your care team immediately.",null,!1,null)
B.mu=new A.d4("skin_nails","Skin / nail changes","\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u062c\u0644\u062f \u0648\u0627\u0644\u0623\u0638\u0627\u0641\u0631","\ud83d\udc85",!1,4,null,"Keep nails clean and short. Moisturise hands daily. Avoid cutting cuticles.",!1,"Are skin or nail changes causing discomfort?")
